fn split_array(list: &Vec<i32>, l: usize) -> (Vec<i32>, Vec<i32>) {
    // Precondition: 0 < l < list.len()
    assert!(l > 0 && l < list.len(), "split index out of bounds");

    // Clone the first part [0..l) into a new Vec<i32>
    let first_part = list[..l].to_vec();
    // Clone the second part [l..len) into another Vec<i32>
    let second_part = list[l..].to_vec();

    (first_part, second_part)
}

fn main() {
    let input = vec![10, 20, 30, 40, 50];
    let split_index = 2;
    let (left, right) = split_array(&input, split_index);

    assert_eq!(left, vec![10, 20]);
    assert_eq!(right, vec![30, 40, 50]);

    println!("Left:  {:?}\nRight: {:?}", left, right);
}